#!/usr/bin/env python3
import argparse,csv,json,math
from pathlib import Path
import multitask_train as mt
def read(p):return list(csv.DictReader(open(p)))
def main():
 p=argparse.ArgumentParser();p.add_argument("--evaluation",type=Path,required=True);p.add_argument("--results",type=Path);p.add_argument("--output",type=Path,default=Path(__file__).with_name("EVALUATION_AUDIT.json"));a=p.parse_args();e=a.evaluation;results=a.results or e.parent/"results/final_report";s=json.loads((e/"SUMMARY.json").read_text());sl=read(e/"slip/metrics.csv");st=read(e/"slip/trials.csv");th=read(e/"slip/thresholds.csv");fm=read(e/"future/metrics.csv");ft=read(e/"future/trials.csv");detail=read(e/"future/trial_axis_horizon.csv");curves=read(e/"slip/descriptive_matched_curves.csv");ci=read(e/"bootstrap/PAIRED_CI.csv");idx=json.loads((e/"INPUT_INDEX.json").read_text());cases=json.loads((e/"cases/SELECTED.json").read_text())
 checks={"summary_complete":s["status"]=="complete","input_models_36":len(idx["runs"])==36,"slip_metric_rows":len(sl)==2976,"slip_threshold_rows":len(th)==624,"future_metric_rows":len(fm)==13824,"future_trial_rows":len(ft)==300,"paired_ci_rows":len(ci)==16,"case_rules_three":len(cases["selected"])==3,"raw_prediction_files_144":len(list((e/"predictions").rglob("*.npz")))==144,"test_absent":not any("test" in str(x).lower() for x in e.rglob("*"))}
 ids={(x["group"],int(x["fold"]),int(x["seed"])) for x in sl};checks["slip_grid_24"]=len(ids)==24 and {x[0] for x in ids}=={"S","J"};checks["all_31_policies_each_role"]=all(len([x for x in sl if x["group"]==g and int(x["fold"])==f and int(x["seed"])==s0 and x["role"]==r])==31 for g,f,s0 in ids for r in ("fit","selection","calibration","validation"))
 checks["square_decomposition"]=all(math.isclose(float(x["future_error_sq"]),float(x["anchor_sq"])+float(x["residual_minus_change_sq"])+float(x["cross_2_anchor_residual"]),rel_tol=2e-5,abs_tol=2e-5) for x in fm)
 checks["ci_support_explicit"]=all(int(x["requested_draws"])==2000 and ((int(x["valid_draws"])>0 and all(math.isfinite(float(x[k])) for k in ("mean","q025","median","q975"))) or (int(x["valid_draws"])==0 and x["support_status"].startswith("unsupported"))) for x in ci)
 checks["censoring_reported"]=sum(float(x["left_censored_events"]) for x in st)>0 and sum(float(x["right_boundary_events"]) for x in st)>0
